function evaluateFollowupPolicy({
  automaticSentCount = 0,
  customerResponded = false,
  humanLock = false,
  commercialStage = null,
  quoteChanged = false,
  delayHours = 23,
}) {
  if (customerResponded) return { action: "cancel", reasonCode: "CUSTOMER_RESPONDED", discountAllowed: false };
  if (humanLock) return { action: "skip", reasonCode: "HUMAN_LOCK_ACTIVE", discountAllowed: false };
  if (["GANHO", "PERDIDO"].includes(commercialStage)) {
    return { action: "cancel", reasonCode: "TERMINAL_COMMERCIAL_STAGE", discountAllowed: false };
  }
  if (quoteChanged) return { action: "cancel", reasonCode: "QUOTE_CHANGED", discountAllowed: false };
  if (automaticSentCount >= 1) {
    return { action: "none", reasonCode: "AUTO_FOLLOWUP_LIMIT_REACHED", discountAllowed: false };
  }
  return {
    action: "schedule",
    reasonCode: "FIRST_AUTOMATIC_FOLLOWUP",
    delayHours,
    discountAllowed: false,
  };
}

return {json:evaluateFollowupPolicy({
  automaticSentCount:Number($json.automatic_sent_count ?? $json.automaticSentCount ?? 0),
  customerResponded:Boolean($json.customer_responded ?? $json.customerResponded),
  humanLock:Boolean($json.human_lock ?? $json.humanLock),
  commercialStage:$json.commercial_stage ?? $json.commercialStage ?? null,
  quoteChanged:Boolean($json.quote_changed ?? $json.quoteChanged),
  delayHours:Number($json.delay_hours ?? $json.delayHours ?? 23),
})};

const policy=$json;
const input=$('Receive Follow-up Context').item.json;
const existing=input.existing_followup ?? null;
const operations=[];

function addHours(iso,hours){
  const date=new Date(iso);
  if(Number.isNaN(date.getTime())) return null;
  return new Date(date.getTime()+hours*3600000).toISOString();
}
function timeReached(now,due){
  const a=new Date(now).getTime();
  const b=new Date(due).getTime();
  return Number.isFinite(a)&&Number.isFinite(b)&&a>=b;
}

if(policy.discountAllowed!==false){
  return {json:{
    status:'blocked',
    policy,
    operations:[],
    blockers:['AUTOMATIC_FOLLOWUP_DISCOUNT_FORBIDDEN']
  }};
}

if(policy.action==='cancel' || policy.action==='skip'){
  if(existing && existing.status==='pending'){
    operations.push({
      action:'CANCEL_FOLLOWUP',
      followup_id:existing.id ?? null,
      reason_code:policy.reasonCode
    });
  }
  return {json:{
    status:'cancelled_or_skipped',
    policy,
    operations,
    blockers:[]
  }};
}

if(policy.action==='none'){
  return {json:{
    status:'no_action',
    policy,
    operations:[],
    blockers:[]
  }};
}

if(policy.action!=='schedule'){
  return {json:{
    status:'blocked',
    policy,
    operations:[],
    blockers:['UNKNOWN_FOLLOWUP_POLICY_ACTION']
  }};
}

const key='followup:'+String(input.customer_event_id)+':quote:'+String(input.quote_version ?? 'na')+':auto1';

if(input.trigger_type==='quote_sent'){
  if(existing && existing.status==='pending'){
    return {json:{status:'already_scheduled',policy,operations:[],blockers:[]}};
  }
  const dueAt=addHours(input.quote_sent_at,policy.delayHours);
  if(!dueAt){
    return {json:{status:'blocked',policy,operations:[],blockers:['QUOTE_SENT_AT_INVALID']}};
  }
  operations.push({
    action:'UPSERT_FOLLOWUP',
    idempotency_key:key,
    customer_event_id:input.customer_event_id,
    due_at:dueAt,
    automatic:true,
    ordinal:1,
    template_key:'FOLLOWUP_23H_NO_DISCOUNT',
    discount_allowed:false,
    status:'pending'
  });
  return {json:{
    status:'scheduled',
    policy,
    operations,
    next_action_at:dueAt,
    blockers:[]
  }};
}

if(input.trigger_type==='schedule_tick'){
  const dueAt=existing?.due_at ?? null;
  if(!existing || existing.status!=='pending'){
    return {json:{status:'no_pending_followup',policy,operations:[],blockers:[]}};
  }
  if(!timeReached(input.now,dueAt)){
    return {json:{status:'not_due',policy,operations:[],next_action_at:dueAt,blockers:[]}};
  }
  operations.push({
    action:'REQUEST_RESPONSE_COMPOSITION',
    customer_event_id:input.customer_event_id,
    response_action:'COMPOSE_FOLLOWUP_23H_NO_DISCOUNT',
    followup_id:existing.id ?? null,
    idempotency_key:key,
    discount_allowed:false
  });
  operations.push({
    action:'EMIT_EVENT',
    event_type:'followup_due',
    customer_event_id:input.customer_event_id,
    followup_id:existing.id ?? null
  });
  return {json:{
    status:'due_shadow',
    policy,
    operations,
    blockers:['SEND_DISABLED']
  }};
}

return {json:{
  status:'no_action',
  policy,
  operations:[],
  blockers:[]
}};
